INSERT INTO quiz_questions(id, level, question, choices_json, correct_index, explanation, source, active) VALUES
('L1-001',1,'Apa kepanjangan dari karhutla?','["Kerusakan hutan dan lahan","Kebakaran hutan dan lahan","Kekeringan hutan dan laut","Kebakaran hutan dan laut"]',1,'Karhutla adalah singkatan dari kebakaran hutan dan lahan.','Materi Dasar Karhutla (lihat halaman Referensi: KLHK/SiPongi, BNPB)',1),
('L1-002',1,'Karhutla dapat terjadi pada area apa saja?','["Hanya di dalam gedung","Hanya di tengah laut","Hutan, semak belukar, kebun, dan lahan gambut","Hanya di jalan beraspal"]',2,'Karhutla terjadi pada hutan maupun lahan bervegetasi, termasuk gambut.','Materi Dasar Karhutla (lihat halaman Referensi: KLHK/SiPongi, BNPB)',1),
('L1-003',1,'Tiga unsur yang diperlukan agar api menyala adalah...','["Air, tanah, dan angin","Asap, abu, dan arang","Kayu, batu, dan air","Bahan bakar, oksigen, dan panas"]',3,'Segitiga api terdiri dari bahan bakar, oksigen, dan panas.','Materi Dasar Karhutla (lihat halaman Referensi: KLHK/SiPongi, BNPB)',1),
('L1-004',1,'Lahan gambut adalah lahan yang...','["Memiliki timbunan bahan organik yang membusuk","Berupa pasir kering di pantai","Seluruhnya terbuat dari batu kapur","Tertutup beton di perkotaan"]',0,'Gambut tersusun dari sisa tumbuhan yang menumpuk dan terurai sebagian.','Materi Dasar Karhutla (lihat halaman Referensi: KLHK/SiPongi, BNPB)',1),
('L1-005',1,'Mengapa kebakaran di lahan gambut sulit dipadamkan?','["Gambut tidak dapat terbakar","Api dapat menjalar dan membara di bawah permukaan","Gambut selalu basah sehingga api cepat padam","Gambut tidak menimbulkan asap"]',1,'Api di gambut dapat bertahan di dalam lapisan tanah sehingga sulit dijangkau.','Materi Dasar Karhutla (lihat halaman Referensi: KLHK/SiPongi, BNPB)',1),
('L1-006',1,'Kabut asap terbentuk terutama karena...','["Embun pagi yang tebal","Uap air dari laut","Asap hasil pembakaran yang menyebar di udara","Debu jalanan saja"]',2,'Asap karhutla yang terkumpul di udara menurunkan jarak pandang dan kualitas udara.','Materi Dasar Karhutla (lihat halaman Referensi: KLHK/SiPongi, BNPB)',1),
('L1-007',1,'Karhutla lebih rentan terjadi pada musim...','["Hujan lebat","Banjir","Pancaroba saja tanpa kering","Kemarau"]',3,'Vegetasi dan tanah yang kering mudah terbakar saat kemarau.','Materi Dasar Karhutla (lihat halaman Referensi: KLHK/SiPongi, BNPB)',1),
('L1-008',1,'Wilayah Indonesia yang memiliki lahan gambut luas antara lain...','["Sumatra, Kalimantan, dan Papua","Hanya Jawa dan Bali","Hanya Nusa Tenggara","Hanya Sulawesi Utara"]',0,'Gambut tersebar luas di Sumatra, Kalimantan, dan Papua.','Materi Dasar Karhutla (lihat halaman Referensi: KLHK/SiPongi, BNPB)',1),
('L1-009',1,'Kapan api paling mudah dikendalikan?','["Saat sudah meluas","Saat masih kecil dan baru muncul","Saat angin kencang","Saat sudah menjadi kobaran besar"]',1,'Api awal lebih mudah dikendalikan, karena itu deteksi dan pelaporan dini penting.','Materi Dasar Karhutla (lihat halaman Referensi: KLHK/SiPongi, BNPB)',1),
('L1-010',1,'Salah satu fungsi hutan bagi lingkungan adalah...','["Menambah polusi udara","Menghasilkan kabut asap","Menyerap karbon dan menjaga tata air","Mengurangi oksigen"]',2,'Hutan menyerap karbon dioksida dan membantu menyimpan serta mengatur air.','Materi Dasar Karhutla (lihat halaman Referensi: KLHK/SiPongi, BNPB)',1),
